from pathlib import Path
import json
R=Path(__file__).resolve().parent
m=json.loads((R/'manifest.json').read_text());c=m['characters']['knight_female_p2']
labels={'idle':'대기','walk':'걷기','attack':'일반 공격','hurt':'피격','dead':'쓰러짐','sit':'앉기','cast':'캐스팅','skill_cleave':'강타','skill_sweep':'폭렬검 · 창 휘두르기','skill_thrust':'꿰뚫기 · 창 찌르기','skill_throw':'창 던지기','skill_guard':'인내 · 반격 · 철벽 자세','skill_enchant':'양손검 가속 · 속성 전환 · 마력 부여','skill_provoke':'도발','skill_double':'회전 강타 · 2연타','skill_crescent':'광월참 · 3연타','skill_charge':'돌격'}
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>기사 · 기본 동작과 스킬 검토</title><style>
:root{color-scheme:dark;font:16px system-ui;background:#17222d;color:#eaf0f1}body{max-width:1150px;margin:32px auto;padding:0 20px}h1{font-size:28px;margin:0}p{color:#adbfc9;line-height:1.7}a{color:#e3be77}button,select{font:inherit;padding:8px 12px;background:#2c4150;color:inherit;border:1px solid #46606d;border-radius:6px;cursor:pointer}button[aria-pressed=true]{background:#b28a45;color:#101820}.bar{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.stage{display:grid;grid-template-columns:1fr 1fr;gap:16px;background:#25313e;border-radius:10px;padding:16px;text-align:center}canvas{image-rendering:pixelated;width:100%;max-width:512px;aspect-ratio:128/120}input{width:100%}.caption{color:#e3be77;min-height:2em}img{image-rendering:pixelated;max-width:100%}.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px}.card{background:#25313e;border-radius:8px;padding:16px}.card img{width:100%}small{color:#adbdc7}table{border-collapse:collapse;width:100%}td,th{padding:8px;text-align:left;border-bottom:1px solid #354653}@media(max-width:600px){.stage{grid-template-columns:1fr}}
</style><h1>기사 · 기본 동작과 스킬</h1><p>r15의 기본 27장 유지 · 16개 스킬 / 10종 모션 · 캐스팅 2장 · 검과 창<br>2등신 · 대기 48px · 128×120 · 발 기준점 (64,112)</p>
<div class="bar"><label>무기 <select id="weapon"><option value="sword">검 / 양손검</option><option value="spear">창</option></select></label><label>크기 <select id="scale"><option value="4">4×</option><option value="1">1×</option></select></label><label>재생 속도 <select id="speed"><option value="1">1×</option><option value="0.5">0.5×</option><option value="0.25">0.25×</option></select></label></div><nav id="actions" class="bar"></nav>
<div class="stage"><section><h3>일반 공격</h3><canvas id="plain" width="128" height="120"></canvas><div id="plainInfo" class="caption"></div></section><section><h3 id="name"></h3><canvas id="active" width="128" height="120"></canvas><div id="info" class="caption"></div></section></div>
<div class="bar"><button id="play">일시정지</button><button id="next">다음 장</button><button id="restart">처음부터</button></div><input id="scrub" aria-label="프레임" type="range" min="0" value="0"><p id="timing"></p>
<h2>같은 크기로 비교</h2><p>왼쪽부터 쿠키 r12 · 기사 r15 · 완성 기사(검) · 완성 기사(창)</p><img src="comparison_4x.png" alt="쿠키와 기사 크기 비교"><p><a href="comparison_1x.png">1× 비교</a> · <a href="skills_contact_sheet.png">검 스킬 전체 시트</a> · <a href="skills_spear_contact_sheet.png">창 스킬 전체 시트</a> · <a href="spear_contact_sheet.png">창 모든 프레임</a> · <a href="manifest.json">Manifest</a> · <a href="NOTES.md">제작 기록</a> · <a href="verification/validation.json">검증 결과</a></p><h2>스킬 GIF</h2><div id="gallery" class="gallery"></div>
<script>const data=__DATA__,labels=__LABELS__,anims=data.animations;let selected='skill_sweep',weapon='sword',playing=true,time=0,last=performance.now();const cache={};for(const w of ['sword','spear'])for(const n of Object.keys(data.frames)){const im=new Image();im.src=`composite/${w}/${n}.png`;cache[w+'/'+n]=im;}const $=id=>document.getElementById(id);function choose(a){selected=a;time=0;$('scrub').max=anims[a].frames.length-1;$('name').textContent=labels[a];for(const b of $('actions').children)b.setAttribute('aria-pressed',b.dataset.a===a);const x=anims[a];$('timing').textContent=`${x.frames.length}장 · ${x.duration}ms · ${x.loop?'반복 동작':'게임에서는 한 번 재생'}${x.hitFrame!==undefined?' · 타격 '+x.hitFrame+'번 장 ('+x.durations.slice(0,x.hitFrame).reduce((a,b)=>a+b,0)+'ms)':' · 타격 프레임 없음'}`;}for(const a of Object.keys(anims)){const b=document.createElement('button');b.textContent=labels[a];b.dataset.a=a;b.onclick=()=>choose(a);$('actions').append(b);}function at(a,t){if(a.loop)t%=a.duration;let s=0;for(let i=0;i<a.frames.length;i++){s+=a.durations[i];if(t<s)return i;}return a.holdLast?a.frames.length-1:-1;}function draw(id,a,t){const cv=$(id),ctx=cv.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.fillStyle='#25313e';ctx.fillRect(0,0,128,120);const i=at(a,t),n=i<0?'idle_0':a.frames[i],im=cache[weapon+'/'+n];if(im.complete)ctx.drawImage(im,0,0);return i;}function tick(now){if(playing)time+=(now-last)*Number($('speed').value);last=now;const a=anims[selected],cycle=Math.max(a.duration,anims.attack.duration)+240;time%=cycle;const i=draw('active',a,time),j=draw('plain',anims.attack,time);$('info').textContent=i<0?'대기 복귀':`${a.frames[i]} · ${a.durations[i]}ms${i===a.hitFrame?' · 타격':''}`;$('plainInfo').textContent=j<0?'대기 복귀':`attack_${j} · ${anims.attack.durations[j]}ms`;if(playing)$('scrub').value=Math.max(0,i);requestAnimationFrame(tick);}function pause(){playing=false;$('play').textContent='재생';}$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'일시정지':'재생';};$('restart').onclick=()=>time=0;$('scrub').oninput=()=>{pause();time=anims[selected].durations.slice(0,Number($('scrub').value)).reduce((a,b)=>a+b,0);};$('next').onclick=()=>{pause();const a=anims[selected],i=(at(a,time)+1)%a.frames.length;$('scrub').value=i;time=a.durations.slice(0,i).reduce((a,b)=>a+b,0);};$('scale').onchange=()=>{for(const id of ['plain','active'])$(id).style.width=(128*Number($('scale').value))+'px';};function gallery(){$('gallery').replaceChildren();for(const a of Object.keys(anims).filter(a=>a.startsWith('skill_'))){const div=document.createElement('section');div.className='card';const stem=a+(weapon==='spear'?'_spear':'');div.innerHTML=`<h3>${labels[a]}</h3><img src="${stem}_4x.gif" alt="${labels[a]} ${weapon}"><p><a href="${stem}_1x.gif">1× GIF</a> · <a href="${stem}_4x.gif">4× GIF</a><br><a href="attack_vs_${a}_${weapon}_4x.gif">일반 공격과 나란히</a></p>`;$('gallery').append(div);}}$('weapon').onchange=()=>{weapon=$('weapon').value;gallery();};choose(selected);gallery();requestAnimationFrame(tick);</script></html>'''
html=html.replace('__DATA__',json.dumps(c,ensure_ascii=False)).replace('__LABELS__',json.dumps(labels,ensure_ascii=False))
(R/'preview.html').write_text(html)
